<?php
use App\DonationCategoryType; use App\Models\DonationCategory; use Illuminate\Support\Facades\Gate; use Illuminate\Support\Str; use Illuminate\Validation\Rule; use Livewire\Attributes\Title; use Livewire\Component; use Livewire\WithPagination;
new #[Title('Donation Categories')] class extends Component { use WithPagination; public string $search=''; public ?int $editing=null; public string $name=''; public string $type='general_donation'; public string $description=''; public string $suggestedAmount=''; public bool $active=true; public bool $featured=false; public bool $website=false; public int $sortOrder=0; public function mount():void{Gate::authorize('viewAny',DonationCategory::class);} public function edit(int $id):void{$c=DonationCategory::findOrFail($id);Gate::authorize('update',$c);$this->editing=$c->id;$this->name=$c->name;$this->type=$c->type->value;$this->description=$c->description??'';$this->suggestedAmount=$c->suggested_amount??'';$this->active=$c->is_active;$this->featured=$c->is_featured;$this->website=$c->display_on_website;$this->sortOrder=$c->sort_order;} public function save():void{$c=$this->editing?DonationCategory::findOrFail($this->editing):new DonationCategory;Gate::authorize($c->exists?'update':'create',$c->exists?$c:DonationCategory::class);$data=$this->validate(['name'=>['required','string','max:150',Rule::unique('donation_categories')->ignore($c)],'type'=>['required',Rule::enum(DonationCategoryType::class)],'description'=>['nullable','max:5000'],'suggestedAmount'=>['nullable','numeric','gt:0'],'sortOrder'=>['integer','min:0']]);$c->fill(['name'=>$data['name'],'slug'=>Str::slug($data['name']).($c->exists?'':'-'.Str::lower(Str::random(5))),'type'=>$data['type'],'description'=>$data['description']?:null,'suggested_amount'=>$data['suggestedAmount']?:null,'is_active'=>$this->active,'is_featured'=>$this->featured,'display_on_website'=>$this->website,'sort_order'=>$data['sortOrder'],'created_by'=>$c->created_by??auth()->id()])->save();$this->reset(['editing','name','description','suggestedAmount','featured','website','sortOrder']);$this->active=true;session()->flash('success',__('Category saved.'));} public function delete(int $id):void{$c=DonationCategory::findOrFail($id);Gate::authorize('delete',$c);$c->delete();} public function categories(){return DonationCategory::withCount('donations')->withSum(['donations as completed_total'=>fn($q)=>$q->completed()],'amount')->when($this->search,fn($q)=>$q->where('name','like','%'.$this->search.'%'))->orderBy('sort_order')->paginate(15);} }; ?>
<div class="mx-auto w-full max-w-7xl space-y-6"><x-admin.page-header :title="__('Donation categories')" :description="__('Control giving classifications and public visibility.')" :eyebrow="__('Giving management')"/><div class="grid gap-6 lg:grid-cols-3"><form wire:submit="save" class="space-y-4 rounded-xl border bg-white p-6 dark:border-zinc-800 dark:bg-zinc-900"><flux:heading>{{$editing?__('Edit category'):__('Add category')}}</flux:heading><flux:input wire:model="name" :label="__('Name')"/><flux:select wire:model="type" :label="__('Type')">@foreach(DonationCategoryType::cases() as $x)<flux:select.option :value="$x->value">{{$x->label()}}</flux:select.option>@endforeach</flux:select><flux:textarea wire:model="description" :label="__('Description')"/><flux:input wire:model="suggestedAmount" type="number" step="0.01" :label="__('Suggested amount')"/><flux:input wire:model="sortOrder" type="number" :label="__('Sort order')"/><flux:checkbox wire:model="active" :label="__('Active')"/><flux:checkbox wire:model="featured" :label="__('Featured')"/><flux:checkbox wire:model="website" :label="__('Show publicly')"/><flux:button type="submit" variant="primary" class="w-full">{{__('Save category')}}</flux:button></form><section class="overflow-hidden rounded-xl border bg-white lg:col-span-2 dark:border-zinc-800 dark:bg-zinc-900"><div class="border-b p-4 dark:border-zinc-800"><flux:input wire:model.live.debounce.300ms="search" :label="__('Search')"/></div><div class="overflow-x-auto"><table class="w-full text-sm"><thead><tr><th class="px-5 py-3 text-left">{{__('Category')}}</th><th class="px-5 py-3">{{__('Gifts')}}</th><th class="px-5 py-3">{{__('Completed')}}</th><th></th></tr></thead><tbody>@foreach($this->categories() as $c)<tr class="border-t dark:border-zinc-800"><td class="px-5 py-4"><strong>{{$c->name}}</strong><p class="text-xs text-slate-500">{{$c->type->label()}} · {{$c->is_active?__('Active'):__('Inactive')}}</p></td><td class="px-5 py-4 text-center">{{$c->donations_count}}</td><td class="px-5 py-4 text-center">{{number_format((float)$c->completed_total,2)}}</td><td class="px-5 py-4 text-right"><flux:button wire:click="edit({{$c->id}})" size="sm">{{__('Edit')}}</flux:button>@can('delete',$c)<flux:button wire:click="delete({{$c->id}})" size="sm" variant="danger">{{__('Delete')}}</flux:button>@endcan</td></tr>@endforeach</tbody></table></div><div class="p-4">{{$this->categories()->links()}}</div></section></div></div>
